functions.useThing:
{
   var _loc2_;
   if(this.accountThing(tThing) >= tNumber)
   {
      _loc2_ = 1;
      while(_loc2_ <= this.number && tNumber > 0)
      {
         if(this["包格" + _loc2_].type == tThing.type && (this["包格" + _loc2_].name == tThing.name || this["包格" + _loc2_].name == undefined))
         {
            if(this["包格" + _loc2_].number == 0 || this["包格" + _loc2_].number == undefined)
            {
               this["包格" + _loc2_].setThing({type:"空格"});
               tNumber -= 1;
            }
            else if(this["包格" + _loc2_].number > tNumber)
            {
               this["包格" + _loc2_].number -= tNumber;
               tNumber = 0;
            }
            else
            {
               tNumber -= this["包格" + _loc2_].number;
               this["包格" + _loc2_].setThing({type:"空格"});
            }
         }
         _loc2_ = _loc2_ + 1;
      }
      return true;
   }
   return false;
}

